-- Practice difficulty references approved 2026-10-14; never calibrated exam scores.
-- Retain retired courses and memberships for administration; original learning data is untouched.
SET LOCAL lock_timeout = '3s';
SET LOCAL statement_timeout = '15s';
UPDATE library_courses SET published=FALSE,revision=revision+1 WHERE id IN ('ielts-foundation','toeic-foundation','communication-basic','communication-everyday','communication-work','communication-natural','ielts-5-0','ielts-6-0','ielts-7-0','ielts-8-0plus','toeic-450plus','toeic-650plus','toeic-800plus','toeic-900plus');
UPDATE library_courses c SET ready=TRUE WHERE c.id='ielts-band-3-0' AND EXISTS(SELECT 1 FROM library_groups g WHERE g.course_id=c.id) AND NOT EXISTS(SELECT 1 FROM library_groups g WHERE g.course_id=c.id AND NOT EXISTS(SELECT 1 FROM library_lessons x WHERE x.group_id=g.id));
