INSERT INTO library_courses(id,goal,title,target_label,description,criteria,coverage_note,position_index,published,ready) VALUES ('ielts-band-3-0','IELTS','Band 3.0','Câu ngắn và thông tin quen thuộc','Độ khó bài luyện tham khảo theo nội dung câu và lượng thông tin cần nghe. Không phải điểm thi, điểm dự đoán hoặc quy đổi CEFR.','Động từ cơ bản, hỏi đáp ngắn; thông tin trực tiếp về người, món ăn và sinh hoạt. Không phân loại chỉ bằng tốc độ phát. Audio đã kiểm tra kỹ thuật, chưa xác minh toàn bộ tốc độ nói, nối âm hoặc giọng đọc.','Cùng một bài gốc và lịch sử học ở mọi mức. Chỉ luyện nghe và chép chính tả. Phân loại nội dung tạm thời; chưa hiệu chuẩn theo đề thi hoặc thử nghiệm người học.',1,TRUE,FALSE);
