INSERT INTO library_courses(id,goal,title,target_label,description,criteria,coverage_note,position_index,published,ready) VALUES ('ielts-band-4-0','IELTS','Band 4.0','Thói quen và kế hoạch','Độ khó bài luyện tham khảo theo nội dung câu và lượng thông tin cần nghe. Không phải điểm thi, điểm dự đoán hoặc quy đổi CEFR.','Hỏi đáp mở rộng, lịch hẹn, tương lai và lời đáp nhấn mạnh; thông tin vẫn chủ yếu trực tiếp. Không phân loại chỉ bằng tốc độ phát. Audio đã kiểm tra kỹ thuật, chưa xác minh toàn bộ tốc độ nói, nối âm hoặc giọng đọc.','Cùng một bài gốc và lịch sử học ở mọi mức. Chỉ luyện nghe và chép chính tả. Phân loại nội dung tạm thời; chưa hiệu chuẩn theo đề thi hoặc thử nghiệm người học.',2,TRUE,FALSE);
