INSERT INTO library_courses(id,goal,title,target_label,description,criteria,coverage_note,position_index,published,ready) VALUES ('toeic-score-500','TOEIC','500','Lịch hẹn và dịch vụ','Độ khó bài luyện tham khảo theo nội dung câu và lượng thông tin cần nghe. Không phải điểm thi, điểm dự đoán hoặc quy đổi CEFR.','Lịch hẹn, yêu cầu, câu bị động, mốc thời gian và thay đổi kế hoạch trong bối cảnh đời sống hoặc công việc. Không phân loại chỉ bằng tốc độ phát. Audio đã kiểm tra kỹ thuật, chưa xác minh toàn bộ tốc độ nói, nối âm hoặc giọng đọc.','Cùng một bài gốc và lịch sử học ở mọi mức. Chỉ luyện nghe và chép chính tả. Phân loại nội dung tạm thời; chưa hiệu chuẩn theo đề thi hoặc thử nghiệm người học.',2,TRUE,FALSE);
