INSERT INTO library_courses(id,goal,title,target_label,description,criteria,coverage_note,position_index,published,ready) VALUES ('toeic-score-700','TOEIC','700','Giải quyết tình huống','Độ khó bài luyện tham khảo theo nội dung câu và lượng thông tin cần nghe. Không phải điểm thi, điểm dự đoán hoặc quy đổi CEFR.','Theo dõi nguyên nhân, lựa chọn thay thế, đổi trả, ngân sách và phân công; câu chứa nhiều thông tin liên kết. Không phân loại chỉ bằng tốc độ phát. Audio đã kiểm tra kỹ thuật, chưa xác minh toàn bộ tốc độ nói, nối âm hoặc giọng đọc.','Cùng một bài gốc và lịch sử học ở mọi mức. Chỉ luyện nghe và chép chính tả. Phân loại nội dung tạm thời; chưa hiệu chuẩn theo đề thi hoặc thử nghiệm người học.',3,TRUE,FALSE);
