INSERT INTO library_courses(id,goal,title,target_label,description,criteria,coverage_note,position_index,published,ready) VALUES ('toeic-score-900plus','TOEIC','900+','Thông tin dày và ý ngầm','Độ khó bài luyện tham khảo theo nội dung câu và lượng thông tin cần nghe. Không phải điểm thi, điểm dự đoán hoặc quy đổi CEFR.','Cần hội thoại hoặc thông báo nghiệp vụ dài, thông tin dày, diễn giải và ý ngầm đã được kiểm tra. Không phân loại chỉ bằng tốc độ phát. Audio đã kiểm tra kỹ thuật, chưa xác minh toàn bộ tốc độ nói, nối âm hoặc giọng đọc.','Chưa có bài phù hợp đã được phân loại ở mức này. Bạn có thể chọn mức khác hoặc Tất cả bài. Phân loại nội dung tạm thời; chưa hiệu chuẩn theo đề thi hoặc thử nghiệm người học.',4,TRUE,FALSE);
