INSERT INTO library_courses(id,goal,title,target_label,description,criteria,coverage_note,position_index,published,ready) VALUES ('communication-cefr-b2','COMMUNICATION','B2','Cấu trúc và sắc thái','Bài giao tiếp theo CEFR tham khảo của bài gốc. Chủ đề và tình huống nằm trong từng mức.','Dùng mức CEFR đang có của bài gốc; mức tham khảo cho nghe chép chính tả, không chứng nhận năng lực tổng thể. Không phân loại chỉ bằng tốc độ phát. Audio đã kiểm tra kỹ thuật, chưa xác minh toàn bộ tốc độ nói, nối âm hoặc giọng đọc.','Cùng một bài gốc và lịch sử học ở mọi mức. Chỉ luyện nghe và chép chính tả.',4,TRUE,FALSE);
