INSERT INTO library_courses(id,goal,title,target_label,description,criteria,coverage_note,position_index,published,ready) VALUES ('communication-cefr-c1','COMMUNICATION','C1','Ngôn ngữ nâng cao','Bài giao tiếp theo CEFR tham khảo của bài gốc. Chủ đề và tình huống nằm trong từng mức.','Dùng mức CEFR đang có của bài gốc; mức tham khảo cho nghe chép chính tả, không chứng nhận năng lực tổng thể. Không phân loại chỉ bằng tốc độ phát. Audio đã kiểm tra kỹ thuật, chưa xác minh toàn bộ tốc độ nói, nối âm hoặc giọng đọc.','Chưa có bài phù hợp đã được phân loại ở mức này. Bạn có thể chọn mức khác hoặc Tất cả bài.',5,TRUE,FALSE);
